    out += '<header class="d-identity" data-part="identity"><h3 class="detail-name">' + esc(e.name) + '</h3>' + (alias ? '<p class="d-en">' + esc(alias) + "</p>" : "") + '<p class="d-kind">' + (kind === "p" ? "인물" : "장소") + "</p>" + deepStudyActionHtml(sid) + "</header>";
